"""
    Find character groups
    """
def find_char_groups(s: Any) -> object {
    pos = 0;
    groups = [];
    escaped = False;
    found = False;
    first = None;
    for c in s {
        if (c == "\\") {
            escaped = not escaped;
        } elif escaped {
            escaped = False;
        } elif ((c == "[") and not found) {
            found = True;
            first = pos;
        } elif ((c == "]") and found) {
            groups.append((first, pos));
        }
        pos += 1;
    }
    return groups;
}

""" in:  ["Col1:Text", "Col2:INT"]
        out: {
                 Col1: TEXT,
                 Col2: INT
             }
    """
def get_ctypes(ColumnsNamesType: Any) -> object {
    ctypes = {};
    for col in ColumnsNamesType {
        splits = col.split(":");
        cname = splits[0];
        ctype = splits[1];
        ctype = ctype.upper();
        ctypes[cname] = ctype;
    }
    return ctypes;
}

